    private LocalDate nextBusinessDay(LocalDate from) {
        LocalDate d = from.plusDays(1);
        while (!isBusinessDay(d.toString())) d = d.plusDays(1);
        return d;
    }

    private LocalDate parseDate(String date) {
        try {
            return LocalDate.parse(date, DateTimeFormatter.ISO_LOCAL_DATE);
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException(e);
        }
    }

    private ZonedDateTime parseInstant(String instant) {
        try {
            return ZonedDateTime.parse(instant);
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException(e);
        }
    }
